--
-- Name: enforce_audit_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_audit_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
        RAISE EXCEPTION 'Audit log is strictly append-only. UPDATE and DELETE operations are forbidden.';
    END;
    $$;


ALTER FUNCTION public.enforce_audit_append_only() OWNER TO postgres;

