--
-- Name: v_entity_submission_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_entity_submission_summary AS
 SELECT s.id AS submission_id,
    s.entity_id,
    o.code AS entity_code,
    o.name AS entity_name,
    s.period_id,
    rp.code AS period_code,
    s.status,
    s.version,
    s.submitted_at,
    count(dp.id) AS total_data_points,
    count(
        CASE
            WHEN (dp.value_numeric IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) AS reported_numeric_points
   FROM (((public.submissions s
     JOIN public.org_nodes o ON ((s.entity_id = o.id)))
     JOIN public.reporting_periods rp ON ((s.period_id = rp.id)))
     LEFT JOIN public.data_points dp ON ((dp.submission_id = s.id)))
  GROUP BY s.id, s.entity_id, o.code, o.name, s.period_id, rp.code, s.status, s.version, s.submitted_at;


ALTER VIEW public.v_entity_submission_summary OWNER TO postgres;

--
-- Name: validation_exceptions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.validation_exceptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    submission_id uuid NOT NULL,
    metric_code character varying(50) NOT NULL,
    rule_id character varying(50) NOT NULL,
    severity character varying(20) NOT NULL,
    description text NOT NULL,
    status character varying(50) NOT NULL,
    raised_by character varying(64),
    assigned_to character varying(64),
    resolution_notes text,
    resolved_by character varying(64),
    resolved_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    is_deleted boolean NOT NULL
);


ALTER TABLE public.validation_exceptions OWNER TO postgres;

--
-- Name: validation_results; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.validation_results (
    submission_id uuid NOT NULL,
    data_point_id character varying(36),
    metric_code character varying(50) NOT NULL,
    rule_id character varying(50) NOT NULL,
    severity character varying(20) NOT NULL,
    message text NOT NULL,
    justification text,
    resolved boolean NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    is_deleted boolean NOT NULL
);


ALTER TABLE public.validation_results OWNER TO postgres;

--
-- Name: value_chain_assessments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.value_chain_assessments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_id uuid NOT NULL,
    period_id uuid NOT NULL,
    esg_score double precision,
    has_iso14001 boolean NOT NULL,
    has_code_of_conduct boolean NOT NULL,
    scope3_reported_tco2e double precision,
    assessment_responses jsonb,
    risk_level character varying(50) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    is_deleted boolean NOT NULL
);


ALTER TABLE public.value_chain_assessments OWNER TO postgres;

--
-- Name: value_chain_partners; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.value_chain_partners (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(255) NOT NULL,
    identifier character varying(100) NOT NULL,
    partner_type character varying(50) NOT NULL,
    category character varying(100) NOT NULL,
    annual_spend_inr_crores double precision NOT NULL,
    spend_share_pct double precision NOT NULL,
    cumulative_spend_pct double precision NOT NULL,
    in_sebi_75_boundary boolean NOT NULL,
    contact_email character varying(255),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    is_deleted boolean NOT NULL
);


ALTER TABLE public.value_chain_partners OWNER TO postgres;

